def finalElement(nums):
    # With a single element no move can be made, so it is the answer
    if len(nums) == 1:
        return nums[0]

    # Alice can delete everything but one end element in her first move,
    # so she secures the larger of the two ends. Bob cannot push it lower.
    return max(nums[0], nums[-1])
